name: coregsm

services:
  backend:
    build:
      context: ./core-backend
      args:
        HTTP_PROXY: ${BUILD_PROXY:-}
        HTTPS_PROXY: ${BUILD_PROXY:-}
        NO_PROXY: localhost,127.0.0.1
    restart: unless-stopped
    env_file: .env
    environment:
      PORT: "3000"
      DB_PATH: /data/coregsm.db
    volumes:
      - coregsm-data:/data
    networks: [internal]
    healthcheck:
      test: ["CMD", "node", "-e", "fetch('http://127.0.0.1:3000/api/health').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))"]
      interval: 15s
      timeout: 5s
      retries: 5
      start_period: 15s

  bot:
    build:
      context: ./core-bot
      args:
        HTTP_PROXY: ${BUILD_PROXY:-}
        HTTPS_PROXY: ${BUILD_PROXY:-}
        NO_PROXY: localhost,127.0.0.1
    restart: unless-stopped
    environment:
      # the Discord token and proxy are configured in the web panel and fetched from the backend
      INTERNAL_TOKEN: ${INTERNAL_TOKEN}
      BACKEND_URL: http://backend:3000
    depends_on:
      backend:
        condition: service_healthy
    networks: [internal]

  frontend:
    build:
      context: ./core-frontend
      args:
        HTTP_PROXY: ${BUILD_PROXY:-}
        HTTPS_PROXY: ${BUILD_PROXY:-}
        NO_PROXY: localhost,127.0.0.1
    restart: unless-stopped
    networks: [internal]

  nginx-proxy:
    build: ./nginx
    restart: unless-stopped
    environment:
      DOMAIN: ${DOMAIN}
    ports:
      - "80:80"
      - "443:443"
    volumes:
      - ./certbot/conf:/etc/letsencrypt:ro
      - ./certbot/www:/var/www/certbot:ro
    depends_on:
      - backend
      - frontend
    networks: [internal]

  certbot:
    image: certbot/certbot
    restart: unless-stopped
    environment:
      HTTPS_PROXY: ${BUILD_PROXY:-}
    volumes:
      - ./certbot/conf:/etc/letsencrypt
      - ./certbot/www:/var/www/certbot
    entrypoint: >
      /bin/sh -c "trap exit TERM;
      while :; do
      certbot renew --quiet --authenticator webroot --webroot-path /var/www/certbot;
      sleep 12h & wait $${!};
      done"
    networks: [internal]

# Only nginx-proxy publishes ports (80/443). Backend, bot and frontend are reachable
# only inside the "internal" network, so Docker cannot bypass the UFW rules for them.
networks:
  internal:

volumes:
  coregsm-data:
__COREGSM_EOF__
  mkdir -p "$APP_DIR/nginx"
  cat > "$APP_DIR/nginx/Dockerfile" << '__COREGSM_EOF__'
FROM nginx:stable-bookworm
COPY templates/ /etc/nginx/templates/
COPY docker-entrypoint.d/40-reload-loop.sh /docker-entrypoint.d/40-reload-loop.sh
RUN chmod +x /docker-entrypoint.d/40-reload-loop.sh
__COREGSM_EOF__
  mkdir -p "$APP_DIR/nginx/docker-entrypoint.d"
  cat > "$APP_DIR/nginx/docker-entrypoint.d/40-reload-loop.sh" << '__COREGSM_EOF__'
#!/bin/sh
# Reload nginx every 6 hours so renewed Let's Encrypt certificates are picked up.
(
  while :; do
    sleep 21600
    nginx -s reload >/dev/null 2>&1 || true
  done
) >/dev/null 2>&1 &
exit 0
__COREGSM_EOF__
  chmod +x "$APP_DIR/nginx/docker-entrypoint.d/40-reload-loop.sh"
  mkdir -p "$APP_DIR/nginx/templates"
  cat > "$APP_DIR/nginx/templates/default.conf.template" << '__COREGSM_EOF__'
limit_req_zone $binary_remote_addr zone=login:10m rate=10r/m;

server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};

    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name ${DOMAIN};

    ssl_certificate     /etc/letsencrypt/live/${DOMAIN}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/${DOMAIN}/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_session_cache   shared:SSL:10m;
    ssl_session_timeout 1d;

    add_header Strict-Transport-Security "max-age=31536000" always;
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options DENY always;
    add_header Referrer-Policy same-origin always;

    resolver 127.0.0.11 valid=10s ipv6=off;
    client_max_body_size 1m;

    # brute-force protection for login and first-run setup
    location ~ ^/api/(auth/login|setup)$ {
        limit_req zone=login burst=5 nodelay;
        set $backend http://backend:3000;
        proxy_pass $backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    location /api/ {
        set $backend http://backend:3000;
        proxy_pass $backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 30s;
    }

    location / {
        set $frontend http://frontend:80;
        proxy_pass $frontend;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
__COREGSM_EOF__
}

write_env() {
  step "Генерация секретов и .env"
  local jwt internal
  SETUP_TOKEN="$(env_get SETUP_TOKEN)"; [ -n "$SETUP_TOKEN" ] || SETUP_TOKEN="$(gen_secret 16)"
  jwt="$(env_get JWT_SECRET)";          [ -n "$jwt" ]      || jwt="$(gen_secret 64)"
  internal="$(env_get INTERNAL_TOKEN)"; [ -n "$internal" ] || internal="$(gen_secret 48)"
  umask 077
  cat > "$APP_DIR/.env" << ENVFILE
# Generated by CoreGSM installer. Keep this file private (chmod 600).
DOMAIN=${DOMAIN}
LE_EMAIL=${LE_EMAIL}
# optional first-start defaults; afterwards the token and proxy are managed in the web panel (Settings)
DISCORD_TOKEN=${DISCORD_TOKEN:-}
# socks5://[user:pass@]host:port or http://[user:pass@]host:port; empty = no proxy
PROXY_URL=${PROXY_URL:-}
# http(s) proxy for Docker image builds and certbot renewal (SOCKS is not supported there)
BUILD_PROXY=${BUILD_PROXY:-}
# one-time code for the first-run setup wizard in the browser
SETUP_TOKEN=${SETUP_TOKEN}
JWT_SECRET=${jwt}
INTERNAL_TOKEN=${internal}
POLL_INTERVAL_SEC=30
ENVFILE
  chmod 600 "$APP_DIR/.env"
  umask 022
  ok "Секреты записаны в $APP_DIR/.env (права 600)"
}

# ---------- 8. TLS ----------
issue_certificate() {
  local conf="$APP_DIR/certbot/conf" live="$APP_DIR/certbot/conf/live/$DOMAIN"
  mkdir -p "$conf" "$APP_DIR/certbot/www"

  if [ "${LOCAL_MODE:-}" = "1" ]; then
    step "SSL-сертификат для локального режима (самоподписанный)"
    if [ -f "$APP_DIR/docker-compose.yml" ]; then
      (cd "$APP_DIR" && docker compose down >/dev/null 2>&1) || true
    fi
    rm -rf "$live"
    mkdir -p "$live"
    local san="DNS:${DOMAIN}"
    [[ "$DOMAIN" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] && san="IP:${DOMAIN}"
    openssl req -x509 -nodes -newkey rsa:2048 -days 825 -subj "/CN=${DOMAIN}" -addext "subjectAltName=${san}" \
      -keyout "$live/privkey.pem" -out "$live/fullchain.pem" >/dev/null 2>&1
    touch "$live/.selfsigned"
    CERT_MODE="local"
    ok "Сертификат создан (825 дней). Браузер покажет предупреждение: это ожидаемо."
    return 0
  fi

  step "Выпуск SSL-сертификата Let's Encrypt (Certbot в Docker)"

  # Stop a previous stack so port 80 is free for the standalone challenge.
  if [ -f "$APP_DIR/docker-compose.yml" ]; then
    (cd "$APP_DIR" && docker compose down >/dev/null 2>&1) || true
  fi

  if [ -f "$live/.selfsigned" ]; then rm -rf "$live" "$conf/archive/$DOMAIN" "$conf/renewal/$DOMAIN.conf"; fi

  if [ -f "$live/fullchain.pem" ]; then
    ok "Действующий сертификат для $DOMAIN уже есть, выпуск пропущен"
    CERT_MODE="letsencrypt"
    return 0
  fi

  if docker run --rm -p 80:80 ${BUILD_PROXY:+-e HTTPS_PROXY=$BUILD_PROXY} \
      -v "$conf:/etc/letsencrypt" -v "$APP_DIR/certbot/www:/var/www/certbot" \
      certbot/certbot certonly --standalone --non-interactive --agree-tos --no-eff-email \
      -m "$LE_EMAIL" -d "$DOMAIN"; then
    CERT_MODE="letsencrypt"
    ok "Сертификат Let's Encrypt выпущен. Автопродление: контейнер certbot."
  else
    warn "Не удалось получить сертификат (проверьте A-запись домена и доступность порта 80)."
    warn "Создаю временный самоподписанный сертификат, чтобы панель всё равно запустилась."
    mkdir -p "$live"
    openssl req -x509 -nodes -newkey rsa:2048 -days 30 -subj "/CN=${DOMAIN}" \
      -keyout "$live/privkey.pem" -out "$live/fullchain.pem" >/dev/null 2>&1
    touch "$live/.selfsigned"
    CERT_MODE="selfsigned"
  fi
}

# ---------- 9. launch ----------
launch() {
  step "Сборка и запуск контейнеров"
  cd "$APP_DIR"
  docker compose up --build -d
  info "Жду готовности панели…"
  local i
  for i in $(seq 1 60); do
    if curl -fsk --noproxy "*" --max-time 3 --resolve "${DOMAIN}:443:127.0.0.1" "https://${DOMAIN}/api/health" >/dev/null 2>&1; then
      ok "Панель отвечает"
      return 0
    fi
    sleep 3
  done
  warn "Панель не ответила за 3 минуты. Логи: cd $APP_DIR && docker compose logs --tail=100"
}

report() {
  local line="════════════════════════════════════════════════════════════"
  echo -e "\n${GREEN}${line}${NC}"
  echo -e "${GREEN}  ✔  CoreGSM установлен${NC}"
  echo -e "${GREEN}${line}${NC}"
  echo -e "  ${BOLD}Панель:${NC}   ${CYAN}https://${DOMAIN}${NC}"
  if curl -fsk --noproxy "*" --max-time 5 --resolve "${DOMAIN}:443:127.0.0.1" "https://${DOMAIN}/api/setup/status" 2>/dev/null | grep -q '"needed":true'; then
    echo -e "  ${BOLD}Код установки:${NC} ${YELLOW}${SETUP_TOKEN}${NC}"
    echo -e "${GREEN}${line}${NC}"
    echo -e "  Откройте панель в браузере и пройдите первичную настройку:"
    echo -e "  введите код установки, придумайте логин и пароль администратора."
  else
    echo -e "${GREEN}${line}${NC}"
    echo -e "  Панель уже настроена: войдите под своим логином и паролем."
  fi
  echo -e "${GREEN}${line}${NC}"
  if [ "${CERT_MODE:-}" = "local" ]; then
    echo -e "  ${YELLOW}Локальный режим:${NC} сертификат самоподписанный, браузер покажет предупреждение."
    echo -e "  Нажмите «Дополнительно» → «Перейти на ${DOMAIN}»."
  fi
  if [ "${CERT_MODE:-}" = "selfsigned" ]; then
    echo -e "  ${RED}Сертификат самоподписанный${NC}: браузер покажет предупреждение."
    echo -e "  Настройте A-запись ${DOMAIN} на этот сервер и повторите: ${BOLD}sudo bash install.sh${NC}"
  fi
  echo -e "  ${DIM}Секреты:  ${APP_DIR}/.env      Логи:  cd ${APP_DIR} && docker compose logs -f${NC}"
  echo -e "  ${DIM}Обновление до новой версии из GitHub:  sudo coregsm-update${NC}"
  echo -e "  ${DIM}Токен Discord-бота, прокси и пароль: в панели, раздел «Настройки».${NC}\n"
}

# /usr/local/bin/coregsm-update: downloads the latest install.sh from GitHub and re-runs it.
install_update_command() {
  cat > /usr/local/bin/.coregsm-update.new << 'UPDATER'
#!/usr/bin/env bash
# Updates CoreGSM to the latest version from GitHub. Secrets, database and certificates are kept.
set -euo pipefail
[ "$(id -u)" -eq 0 ] || { echo "Запустите от root: sudo coregsm-update" >&2; exit 1; }
URL="${COREGSM_URL:-https://raw.githubusercontent.com/RJ-Bond/CoreGSM/main/install.sh}"
proxy="$(grep -E '^PROXY_URL=' /app/.env 2>/dev/null | cut -d= -f2- || true)"
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
echo "Скачиваю $URL"
curl -fsSL ${proxy:+--proxy "${proxy/#socks5:/socks5h:}"} "$URL" -o "$tmp"
bash -n "$tmp"
echo "Получено $(wc -l < "$tmp") строк, запускаю обновление…"
SKIP_UPDATE=1 bash "$tmp" "$@"
UPDATER
  chmod +x /usr/local/bin/.coregsm-update.new
  # atomic replace: a running updater keeps reading its old file safely
  mv -f /usr/local/bin/.coregsm-update.new /usr/local/bin/coregsm-update
}

main() {
  banner
  preflight
  setup_proxy
  system_update
  base_packages
  install_docker
  collect_input
  setup_firewall
  step "Создание файлов проекта в $APP_DIR"
  generate_project
  ok "Файлы проекта созданы"
  write_env
  install_update_command
  issue_certificate
  launch
  report
}

main "$@"
